input.command:
tsc -p . && echo TSC_OK
OUT=$(mktemp -d) && tsc -p . --noEmit false --outDir "$OUT" --module commonjs --target es2022 && echo '{"type":"commonjs"}' > "$OUT/package.json" && cat > "$OUT/check.cjs" <<'EOF'
const assert = require('node:assert');
globalThis.localStorage = { getItem: () => 't' };
let body;
globalThis.fetch = async (url) => ({ ok: true, status: 200, json: async () => body, url });
const { listReports, reportsScreen } = require('./features/reports/index.js');
(async () => {
  body = [{ month: '2026-09', totalCents: 123456 }, { month: '2026-10', totalCents: 0 }];
  assert.strictEqual(reportsScreen(await listReports()), '2026-09: $1,234.56\n2026-10: $0.00');
  assert.strictEqual(reportsScreen([]), 'No reports yet.');
  body = [{ month: '2026-09', totalCents: '12' }];
  await assert.rejects(listReports(), /Unexpected/);
  body = { month: '2026-09', totalCents: 1 };
  await assert.rejects(listReports(), /Unexpected/);
  console.log('CHECK_OK');
})();
EOF
node "$OUT/check.cjs"; rm -rf "$OUT"; git status --short

